/* Company invoices at checkout, a store's choice (round chk-1021): "Buying for a business", the box where a buyer adds a company's name, tax number and address for an invoice made out to it, is now shown only where Settings › Checkout › Company invoices is on, kept as `businessInvoice` in the checkout object `store_settings.checkout` (part 109), off for a new store (lib/store/checkout-config.ts). Every checkout used to show it. This turns it on, once, for the stores that already relied on it: a store that has had an order with company details (`orders.business_details`, part 36; `orders.creator_id`, part 32), and a store that filled in its own tax number in Store details › Business details (`store_settings.legal`, part 153), the sign of a business that issues invoices. A store that has set it either way is left as it chose. Every other store reads it as off, as a new one does. Writes only that one key of the checkout object, adding a settings row where a store with company orders had none; no order and no other setting changes. Needs part 109, and skips with a notice where store_settings is not there; reads only the columns of parts 32, 36 and 153 that exist. Safe to run again: a second run finds every such store already set. Until it runs, every store reads it as off and its checkout hides the box. */
DO $do$ BEGIN IF to_regclass('public.store_settings') IS NULL THEN RAISE NOTICE 'company invoices: store_settings is not there yet (part 109).'; RETURN; END IF; IF to_regclass('public.orders') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'business_details') AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'creator_id') THEN INSERT INTO public.store_settings (creator_id, checkout) SELECT DISTINCT o.creator_id, '{"businessInvoice": true}'::jsonb FROM public.orders o JOIN public.creators c ON c.id = o.creator_id WHERE o.business_details IS NOT NULL ON CONFLICT (creator_id) DO UPDATE SET checkout = public.store_settings.checkout || '{"businessInvoice": true}'::jsonb, updated_at = now() WHERE NOT (public.store_settings.checkout ? 'businessInvoice'); END IF; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'store_settings' AND column_name = 'legal') THEN UPDATE public.store_settings s SET checkout = s.checkout || '{"businessInvoice": true}'::jsonb, updated_at = now() WHERE NOT (s.checkout ? 'businessInvoice') AND jsonb_typeof(s.legal) = 'object' AND coalesce(btrim(s.legal ->> 'taxId'), '') <> ''; END IF; END $do$;
